  "scenario_id": "sc-8a9fa1",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "Death",
      "years": [2015, 2024],
      "pattern": "volatility",
      "direction": "dispersion",
      "magnitude": "Empirical YoY SD of A/E = 0.349 vs Poisson 0.048 (x7.3 overdispersion); yearly A/E oscillates 0.734-1.522 around a flat baseline (overall A/E 0.997), with no sustained level shift",
      "confidence": 0.85,
      "evidence": [
        "artifacts/ae_death_by_year.csv: A/E = 0.868, 1.084, 1.248, 1.522, 0.734, 1.137, 0.942, 0.908, 0.925, 0.884 — large year-to-year swings (peak 1.522 in 2018, trough 0.734 in 2019) that revert rather than hold a new level",
        "evidence pack: empirical YoY SD 0.3485 vs Poisson 0.0477 (x7.3, well above the x6 volatility threshold); onset ratio 1.75 (largest 1-yr move exceeds net excursion => oscillation, not a held level); overall A/E 0.997 (level stays flat); Poisson null flagged INVALID for this line"
      ],
      "recommended_action": "Poisson z-scores are invalid on this line, so do NOT flag individual years (e.g. the 2018 spike) against the Poisson null. Treat it as a dispersion problem: reconcile the Death expected-claims / mortality basis with the book's actual age-sex mix and claim coding, investigate data-quality, timing, or book-composition changes that could drive the 2018 peak / 2019 trough, and re-estimate the line's variance model before any pricing or valuation adjustment. CI, TPD and IP (incl. IP termination by diagnosis) are consistent with sampling noise and need no action."
    }
  ]
}

